#include "physics/CCPhysicsWorldQuery.h"
#if CC_USE_PHYSICS

#include <algorithm>
#include <cfloat>

#include "chipmunk/chipmunk_private.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

namespace
{
    // Build a shape filter matching every shape whose category bitmask
    // intersects the given category mask.
    inline cpShapeFilter makeQueryFilter(unsigned int categoryMask)
    {
        cpShapeFilter filter = { 0, CP_ALL_CATEGORIES, (cpBitmask)categoryMask };
        return filter;
    }

    inline PhysicsShape* toPhysicsShape(cpShape* shape)
    {
        return shape == nullptr ? nullptr : static_cast<PhysicsShape*>(cpShapeGetUserData(shape));
    }

    inline PhysicsBody* toPhysicsBody(cpShape* shape)
    {
        PhysicsShape* physicsShape = toPhysicsShape(shape);
        return physicsShape == nullptr ? nullptr : physicsShape->getBody();
    }

    void pushUniqueBody(std::vector<PhysicsBody*>& bodies, PhysicsBody* body)
    {
        if (body != nullptr
            && std::find(bodies.begin(), bodies.end(), body) == bodies.end())
        {
            bodies.push_back(body);
        }
    }

    void pointQueryAllCallback(cpShape* shape, cpVect point, cpFloat distance, cpVect gradient, void* data)
    {
        auto* results = static_cast<std::vector<PhysicsNearestResult>*>(data);
        PhysicsNearestResult result = {
            toPhysicsShape(shape),
            PhysicsHelper::cpv2point(point),
            PhysicsHelper::cpfloat2float(distance),
            PhysicsHelper::cpv2point(gradient)
        };
        results->push_back(result);
    }

    void segmentQueryCallback(cpShape* shape, cpVect point, cpVect normal, cpFloat alpha, void* data)
    {
        auto* results = static_cast<std::vector<PhysicsSegmentQueryResult>*>(data);
        PhysicsSegmentQueryResult result = {
            toPhysicsShape(shape),
            PhysicsHelper::cpv2point(point),
            PhysicsHelper::cpv2point(normal),
            PhysicsHelper::cpfloat2float(alpha)
        };
        results->push_back(result);
    }

    void bbQueryCallback(cpShape* shape, void* data)
    {
        auto* results = static_cast<std::vector<PhysicsBBQueryResult>*>(data);
        PhysicsBBQueryResult result = { toPhysicsShape(shape) };
        results->push_back(result);
    }

    void countBodiesCallback(cpShape* shape, void* data)
    {
        auto* bodies = static_cast<std::vector<PhysicsBody*>*>(data);
        pushUniqueBody(*bodies, toPhysicsBody(shape));
    }

    void rayBodiesCallback(cpShape* shape, cpVect /*point*/, cpVect /*normal*/, cpFloat /*alpha*/, void* data)
    {
        auto* bodies = static_cast<std::vector<PhysicsBody*>*>(data);
        pushUniqueBody(*bodies, toPhysicsBody(shape));
    }

    void circleBodiesCallback(cpShape* shape, cpVect /*point*/, cpFloat /*distance*/, cpVect /*gradient*/, void* data)
    {
        auto* bodies = static_cast<std::vector<PhysicsBody*>*>(data);
        pushUniqueBody(*bodies, toPhysicsBody(shape));
    }

    struct LineOfSightContext
    {
        bool blocked;
    };

    void lineOfSightCallback(cpShape* shape, cpVect /*point*/, cpVect /*normal*/, cpFloat /*alpha*/, void* data)
    {
        // Sensors do not block the line of sight.
        if (!cpShapeGetSensor(shape))
        {
            static_cast<LineOfSightContext*>(data)->blocked = true;
        }
    }

    struct ContactCollectContext
    {
        std::vector<PhysicsContactPairInfo>* contacts;
    };

    void collectArbiterCallback(cpBody* body, cpArbiter* arbiter, void* data)
    {
        cpBody* bodyA = nullptr;
        cpBody* bodyB = nullptr;
        cpArbiterGetBodies(arbiter, &bodyA, &bodyB);

        // Each arbiter is visited once per involved body; keep only the visit
        // from the first body so each contact pair is reported exactly once.
        if (body != bodyA)
        {
            return;
        }

        auto* context = static_cast<ContactCollectContext*>(data);
        int count = cpArbiterGetCount(arbiter);

        PhysicsContactPairInfo info = {
            static_cast<PhysicsBody*>(cpBodyGetUserData(bodyA)),
            static_cast<PhysicsBody*>(cpBodyGetUserData(bodyB)),
            count > 0 ? PhysicsHelper::cpv2point(cpArbiterGetPointA(arbiter, 0)) : Vec2::ZERO,
            count > 0 ? PhysicsHelper::cpv2point(cpArbiterGetNormal(arbiter)) : Vec2::ZERO,
            count > 0 ? PhysicsHelper::cpfloat2float(cpArbiterGetDepth(arbiter, 0)) : 0.0f
        };
        context->contacts->push_back(info);
    }

    void eachBodyCallback(cpBody* body, void* data)
    {
        cpBodyEachArbiter(body, collectArbiterCallback, data);
    }
}

PhysicsWorldQuery::PhysicsWorldQuery()
: _space(nullptr)
, _initialized(false)
{
}

PhysicsWorldQuery::~PhysicsWorldQuery()
{
}

bool PhysicsWorldQuery::init(cpSpace* space)
{
    _space = space;
    _initialized = (space != nullptr);
    return _initialized;
}

PhysicsNearestResult PhysicsWorldQuery::queryNearestPoint(const Vec2& point, float maxDistance, unsigned int categoryMask)
{
    PhysicsNearestResult result = { nullptr, Vec2::ZERO, -1.0f, Vec2::ZERO };
    if (_space == nullptr)
    {
        return result;
    }

    cpPointQueryInfo info;
    cpShape* shape = cpSpacePointQueryNearest(_space,
                                              PhysicsHelper::point2cpv(point),
                                              (cpFloat)maxDistance,
                                              makeQueryFilter(categoryMask),
                                              &info);
    if (shape != nullptr)
    {
        result.shape = toPhysicsShape(shape);
        result.point = PhysicsHelper::cpv2point(info.point);
        result.distance = PhysicsHelper::cpfloat2float(info.distance);
        result.gradient = PhysicsHelper::cpv2point(info.gradient);
    }
    return result;
}

std::vector<PhysicsSegmentQueryResult> PhysicsWorldQuery::querySegment(const Vec2& start, const Vec2& end, float radius, unsigned int categoryMask)
{
    std::vector<PhysicsSegmentQueryResult> results;
    if (_space == nullptr)
    {
        return results;
    }

    cpSpaceSegmentQuery(_space,
                        PhysicsHelper::point2cpv(start),
                        PhysicsHelper::point2cpv(end),
                        (cpFloat)radius,
                        makeQueryFilter(categoryMask),
                        segmentQueryCallback,
                        &results);
    return results;
}

PhysicsSegmentQueryResult PhysicsWorldQuery::querySegmentFirst(const Vec2& start, const Vec2& end, float radius, unsigned int categoryMask)
{
    PhysicsSegmentQueryResult result = { nullptr, Vec2::ZERO, Vec2::ZERO, 1.0f };
    if (_space == nullptr)
    {
        return result;
    }

    cpSegmentQueryInfo info;
    if (cpSpaceSegmentQueryFirst(_space,
                                 PhysicsHelper::point2cpv(start),
                                 PhysicsHelper::point2cpv(end),
                                 (cpFloat)radius,
                                 makeQueryFilter(categoryMask),
                                 &info))
    {
        result.shape = toPhysicsShape(info.shape);
        result.point = PhysicsHelper::cpv2point(info.point);
        result.normal = PhysicsHelper::cpv2point(info.normal);
        result.alpha = PhysicsHelper::cpfloat2float(info.alpha);
    }
    return result;
}

std::vector<PhysicsBBQueryResult> PhysicsWorldQuery::queryBoundingBox(const Rect& rect, unsigned int categoryMask)
{
    std::vector<PhysicsBBQueryResult> results;
    if (_space == nullptr)
    {
        return results;
    }

    cpSpaceBBQuery(_space,
                   PhysicsHelper::rect2cpbb(rect),
                   makeQueryFilter(categoryMask),
                   bbQueryCallback,
                   &results);
    return results;
}

std::vector<PhysicsNearestResult> PhysicsWorldQuery::queryPointAll(const Vec2& point, float maxDistance, unsigned int categoryMask)
{
    std::vector<PhysicsNearestResult> results;
    if (_space == nullptr)
    {
        return results;
    }

    cpSpacePointQuery(_space,
                      PhysicsHelper::point2cpv(point),
                      (cpFloat)maxDistance,
                      makeQueryFilter(categoryMask),
                      pointQueryAllCallback,
                      &results);
    return results;
}

int PhysicsWorldQuery::countBodiesInRect(const Rect& rect, unsigned int categoryMask)
{
    if (_space == nullptr)
    {
        return 0;
    }

    std::vector<PhysicsBody*> bodies;
    cpSpaceBBQuery(_space,
                   PhysicsHelper::rect2cpbb(rect),
                   makeQueryFilter(categoryMask),
                   countBodiesCallback,
                   &bodies);
    return static_cast<int>(bodies.size());
}

bool PhysicsWorldQuery::isPointOccupied(const Vec2& point, unsigned int categoryMask)
{
    if (_space == nullptr)
    {
        return false;
    }

    // A max distance of 0 only matches shapes that actually contain the point.
    cpShape* shape = cpSpacePointQueryNearest(_space,
                                              PhysicsHelper::point2cpv(point),
                                              0,
                                              makeQueryFilter(categoryMask),
                                              nullptr);
    return shape != nullptr;
}

float PhysicsWorldQuery::distanceToNearestBody(const Vec2& point, unsigned int categoryMask)
{
    if (_space == nullptr)
    {
        return -1.0f;
    }

    cpPointQueryInfo info;
    cpShape* shape = cpSpacePointQueryNearest(_space,
                                              PhysicsHelper::point2cpv(point),
                                              (cpFloat)FLT_MAX,
                                              makeQueryFilter(categoryMask),
                                              &info);
    if (shape == nullptr)
    {
        return -1.0f;
    }
    float distance = PhysicsHelper::cpfloat2float(info.distance);
    return distance < 0.0f ? 0.0f : distance;
}

std::vector<PhysicsContactPairInfo> PhysicsWorldQuery::getActiveContacts()
{
    std::vector<PhysicsContactPairInfo> contacts;
    if (_space == nullptr)
    {
        return contacts;
    }

    ContactCollectContext context = { &contacts };
    cpSpaceEachBody(_space, eachBodyCallback, &context);
    return contacts;
}

std::vector<PhysicsBody*> PhysicsWorldQuery::getBodiesAlongRay(const Vec2& start, const Vec2& end, unsigned int categoryMask)
{
    std::vector<PhysicsBody*> bodies;
    if (_space == nullptr)
    {
        return bodies;
    }

    cpSpaceSegmentQuery(_space,
                        PhysicsHelper::point2cpv(start),
                        PhysicsHelper::point2cpv(end),
                        0,
                        makeQueryFilter(categoryMask),
                        rayBodiesCallback,
                        &bodies);
    return bodies;
}

PhysicsBody* PhysicsWorldQuery::getBodyAtPoint(const Vec2& point)
{
    if (_space == nullptr)
    {
        return nullptr;
    }

    cpShape* shape = cpSpacePointQueryNearest(_space,
                                              PhysicsHelper::point2cpv(point),
                                              0,
                                              CP_SHAPE_FILTER_ALL,
                                              nullptr);
    return toPhysicsBody(shape);
}

std::vector<PhysicsBody*> PhysicsWorldQuery::getBodiesInCircle(const Vec2& center, float radius, unsigned int categoryMask)
{
    std::vector<PhysicsBody*> bodies;
    if (_space == nullptr)
    {
        return bodies;
    }

    cpSpacePointQuery(_space,
                      PhysicsHelper::point2cpv(center),
                      (cpFloat)radius,
                      makeQueryFilter(categoryMask),
                      circleBodiesCallback,
                      &bodies);
    return bodies;
}

bool PhysicsWorldQuery::lineOfSight(const Vec2& start, const Vec2& end, unsigned int blockMask)
{
    if (_space == nullptr)
    {
        return true;
    }

    LineOfSightContext context = { false };
    cpSpaceSegmentQuery(_space,
                        PhysicsHelper::point2cpv(start),
                        PhysicsHelper::point2cpv(end),
                        0,
                        makeQueryFilter(blockMask),
                        lineOfSightCallback,
                        &context);
    return !context.blocked;
}

float PhysicsWorldQuery::computePathClearance(const Vec2* path, int pathCount, unsigned int blockMask)
{
    if (_space == nullptr || path == nullptr || pathCount <= 0)
    {
        return -1.0f;
    }

    cpShapeFilter filter = makeQueryFilter(blockMask);

    // A path segment crossing a blocking shape means zero clearance.
    for (int i = 0; i < pathCount - 1; ++i)
    {
        if (cpSpaceSegmentQueryFirst(_space,
                                     PhysicsHelper::point2cpv(path[i]),
                                     PhysicsHelper::point2cpv(path[i + 1]),
                                     0,
                                     filter,
                                     nullptr))
        {
            return 0.0f;
        }
    }

    // Sample along the path, tracking the distance to the closest blocking
    // shape. The query radius shrinks as better clearances are found.
    static const int SAMPLES_PER_SEGMENT = 8;
    float clearance = FLT_MAX;
    for (int i = 0; i < pathCount; ++i)
    {
        Vec2 segment = (i < pathCount - 1) ? (path[i + 1] - path[i]) : Vec2::ZERO;
        int sampleCount = (i < pathCount - 1) ? SAMPLES_PER_SEGMENT : 0;
        for (int s = 0; s <= sampleCount; ++s)
        {
            Vec2 sample = path[i] + segment * ((float)s / (float)(sampleCount > 0 ? sampleCount : 1));
            cpPointQueryInfo info;
            cpShape* shape = cpSpacePointQueryNearest(_space,
                                                      PhysicsHelper::point2cpv(sample),
                                                      (cpFloat)clearance,
                                                      filter,
                                                      &info);
            if (shape != nullptr && info.distance < (cpFloat)clearance)
            {
                clearance = PhysicsHelper::cpfloat2float(info.distance);
            }
        }
    }

    if (clearance == FLT_MAX)
    {
        return -1.0f;
    }
    return clearance < 0.0f ? 0.0f : clearance;
}

std::vector<Vec2> PhysicsWorldQuery::findOpenPositions(const Rect& searchArea, float spacing, float clearance, unsigned int blockMask)
{
    std::vector<Vec2> positions;
    if (_space == nullptr || spacing <= 0.0f || clearance < 0.0f)
    {
        return positions;
    }

    cpShapeFilter filter = makeQueryFilter(blockMask);
    float minX = searchArea.getMinX();
    float maxX = searchArea.getMaxX();
    float minY = searchArea.getMinY();
    float maxY = searchArea.getMaxY();
    float halfSpacing = spacing * 0.5f;

    for (float y = minY + halfSpacing; y <= maxY; y += spacing)
    {
        for (float x = minX + halfSpacing; x <= maxX; x += spacing)
        {
            // Reject candidates lying within the clearance of a blocking shape.
            cpShape* shape = cpSpacePointQueryNearest(_space,
                                                      PhysicsHelper::point2cpv(Vec2(x, y)),
                                                      (cpFloat)clearance,
                                                      filter,
                                                      nullptr);
            if (shape == nullptr)
            {
                positions.push_back(Vec2(x, y));
            }
        }
    }
    return positions;
}

NS_CC_END

#endif // CC_USE_PHYSICS

