121	        cpBody* bodyB = nullptr;
122	        cpArbiterGetBodies(arbiter, &bodyA, &bodyB);
123	
124	        // Each arbiter is visited once per involved body; keep only the visit
125	        // from the first body so each contact pair is reported exactly once.
126	        if (body != bodyA)
127	        {
128	            return;
129	        }
130	
131	        auto* context = static_cast<ContactCollectContext*>(data);
132	        int count = cpArbiterGetCount(arbiter);
133	
134	        PhysicsContactPairInfo info = {
135	            static_cast<PhysicsBody*>(cpBodyGetUserData(bodyA)),
136	            static_cast<PhysicsBody*>(cpBodyGetUserData(bodyB)),
137	            count > 0 ? PhysicsHelper::cpv2point(cpArbiterGetPointA(arbiter, 0)) : Vec2::ZERO,
138	            count > 0 ? PhysicsHelper::cpv2point(cpArbiterGetNormal(arbiter)) : Vec2::ZERO,
139	            count > 0 ? PhysicsHelper::cpfloat2float(cpArbiterGetDepth(arbiter, 0)) : 0.0f
140	        };
141	        context->contacts->push_back(info);
