402	float PhysicsWorldQuery::computePathClearance(const Vec2* path, int pathCount, unsigned int blockMask)
403	{
404	    if (_space == nullptr || path == nullptr || pathCount <= 0)
405	    {
406	        return -1.0f;
407	    }
408	
409	    cpShapeFilter filter = makeQueryFilter(blockMask);
410	
411	    // A path segment crossing a blocking shape means zero clearance.
412	    for (int i = 0; i < pathCount - 1; ++i)
413	    {
414	        cpSegmentQueryInfo segmentInfo;
415	        if (cpSpaceSegmentQueryFirst(_space,
416	                                     PhysicsHelper::point2cpv(path[i]),
417	                                     PhysicsHelper::point2cpv(path[i + 1]),
418	                                     0,
419	                                     filter,
420	                                     &segmentInfo))
421	        {
422	            return 0.0f;
423	        }
424	    }
425	
426	    // Sample along the path, tracking the distance to the closest blocking
427	    // shape. The query radius shrinks as better clearances are found.
428	    static const int SAMPLES_PER_SEGMENT = 8;
429	    float clearance = FLT_MAX;
430	    for (int i = 0; i < pathCount; ++i)
431	    {
432	        Vec2 segment = (i < pathCount - 1) ? (path[i + 1] - path[i]) : Vec2::ZERO;
433	        int sampleCount = (i < pathCount - 1) ? SAMPLES_PER_SEGMENT : 0;
434	        for (int s = 0; s <= sampleCount; ++s)
435	        {
436	            Vec2 sample = path[i] + segment * ((float)s / (float)(sampleCount > 0 ? sampleCount : 1));
437	            cpPointQueryInfo info;
438	            cpShape* shape = cpSpacePointQueryNearest(_space,
439	                                                      PhysicsHelper::point2cpv(sample),
440	                                                      (cpFloat)clearance,
441	                                                      filter,
442	                                                      &info);
443	            if (shape != nullptr && info.distance < (cpFloat)clearance)
444	            {
445	                clearance = PhysicsHelper::cpfloat2float(info.distance);
446	            }
447	        }
448	    }
449	
450	    if (clearance == FLT_MAX)
451	    {
452	        return -1.0f;
453	    }
454	    return clearance < 0.0f ? 0.0f : clearance;
455	}
