457	std::vector<Vec2> PhysicsWorldQuery::findOpenPositions(const Rect& searchArea, float spacing, float clearance, unsigned int blockMask)
458	{
459	    std::vector<Vec2> positions;
460	    if (_space == nullptr || spacing <= 0.0f || clearance < 0.0f)
461	    {
462	        return positions;
463	    }
464	
465	    cpShapeFilter filter = makeQueryFilter(blockMask);
466	    float minX = searchArea.getMinX();
467	    float maxX = searchArea.getMaxX();
468	    float minY = searchArea.getMinY();
469	    float maxY = searchArea.getMaxY();
470	    float halfSpacing = spacing * 0.5f;
471	
472	    for (float y = minY + halfSpacing; y <= maxY; y += spacing)
473	    {
474	        for (float x = minX + halfSpacing; x <= maxX; x += spacing)
475	        {
476	            // Reject candidates lying within the clearance of a blocking shape.
477	            cpPointQueryInfo info;
478	            cpShape* shape = cpSpacePointQueryNearest(_space,
479	                                                      PhysicsHelper::point2cpv(Vec2(x, y)),
480	                                                      (cpFloat)clearance,
481	                                                      filter,
482	                                                      &info);
483	            if (shape == nullptr)
484	            {
485	                positions.push_back(Vec2(x, y));
486	            }
487	        }
488	    }
489	    return positions;
490	}
